#include <stdio.h>

int main(void) {
    int l, u, k, primeiro = 1;
    scanf("%d %d %d", &l, &u, &k);
    int ini = l + (k - ((l % k + k) % k));
    for (int i = ini; i < u; i += k) {
        if (!primeiro) printf(" ");
        printf("%d", i);
        primeiro = 0;
    }
    printf("\n");
    return 0;
}

#include <stdio.h>

int main(void) {
    int a, b, c, aux;
    scanf("%d %d %d", &a, &b, &c);
    if (a > b) { aux = a; a = b; b = aux; }
    if (a > c) { aux = a; a = c; c = aux; }
    if (b > c) { aux = b; b = c; c = aux; }
    printf("%d %d %d\n", a, b, c);
    return 0;
}

#include <stdio.h>

int main(void) {
    int data, dia, mes, ano, vd = 1;
    scanf("%d", &data);
    dia = data / 1000000;
    mes = (data % 1000000) / 10000;
    ano = data % 10000;
    if (ano < 1 || mes < 1 || mes > 12 || dia < 1 || dia > 31) {
        vd = 0;
    } else if ((mes == 4 || mes == 6 || mes == 9 || mes == 11) && dia > 30) {
        vd = 0;
    } else if (mes == 2) {
        int bissexto = (ano % 4 == 0 && ano % 100 != 0) || (ano % 400 == 0);
        if (dia > (bissexto ? 29 : 28)) vd = 0;
    }
    printf("%s\n", vd ? "DATA VALIDA" : "DATA INVALIDA");
    return 0;
}

#include <stdio.h>
#include <math.h>

int main(void) {
    double x;
    scanf("%lf", &x);
    if (x > 4.0 || x < -4.0) {
        double fx = (5.0 * x + 3.0) / sqrt(x * x - 16.0);
        printf("%.4f\n", fx);
    } else {
        printf("NAO PODE SER FEITA\n");
    }
    return 0;
}

#include <stdio.h>

int main(void) {
    int base, expo;
    scanf("%d %d", &base, &expo);
    if (base >= 2 && expo > 1) {
        long long pot = 1;
        for (int i = 1; i <= expo; i++) {
            pot *= base;
        }
        printf("%lld\n", pot);
    } else {
        printf("Nao satisfazem\n");
    }
    return 0;
}

#include <stdio.h>

int main(void) {
    int f1, f2, dec;
    scanf("%d %d %d", &f1, &f2, &dec);
    for (int t = f1; t >= f2; t -= dec) {
        double c = 5.0 * (t - 32) / 9.0;
        printf("%d %.2f\n", t, c);
    }
    return 0;
}

